create sequence public.seq_gate_pass start 1;
create table public.gate_passes(gate_pass_id uuid primary key default gen_random_uuid(),serial_no text not null unique,pass_type text not null check(pass_type in('RETURNABLE','NON_RETURNABLE')),company_name text,address text,pass_date date not null default current_date,pass_time time not null default localtime,person_name text,vehicle_no text,dispatcher text,reason text,prepared_by text,receiver text,authorized_signature_by text,status text not null default 'ISSUED' check(status in('ISSUED','RETURNED','CANCELLED')),created_at timestamptz not null default now(),created_by text not null default 'system',updated_at timestamptz not null default now(),updated_by text);
create table public.gate_pass_lines(gate_pass_line_id uuid primary key default gen_random_uuid(),gate_pass_id uuid not null references public.gate_passes(gate_pass_id) on delete cascade,line_no int not null,description text not null,quantity numeric not null check(quantity>0),uom_text text not null default 'PCS',remarks text,created_at timestamptz not null default now(),created_by text not null default 'system',updated_at timestamptz not null default now(),updated_by text,unique(gate_pass_id,line_no));
create or replace function public.issue_gate_pass(p_type text,p_company text,p_address text,p_person text,p_vehicle text,p_dispatcher text,p_reason text,p_prepared text,p_receiver text,p_authorized text,p_lines jsonb)returns uuid language plpgsql security definer set search_path=public as $$ declare v_id uuid;v_no text;v_line jsonb;v_n int:=0;begin if not has_factory_role(auth.uid(),array['admin','store'])then raise exception'not authorized';end if;if p_type not in('RETURNABLE','NON_RETURNABLE')then raise exception'invalid pass type';end if;if jsonb_typeof(p_lines)<>'array'or jsonb_array_length(p_lines)=0 then raise exception'at least one line is required';end if;v_no:='GP-'||to_char(current_date,'YYYYMMDD')||'-'||lpad(nextval('seq_gate_pass')::text,4,'0');insert into gate_passes(serial_no,pass_type,company_name,address,person_name,vehicle_no,dispatcher,reason,prepared_by,receiver,authorized_signature_by,created_by)values(v_no,p_type,p_company,p_address,p_person,p_vehicle,p_dispatcher,p_reason,p_prepared,p_receiver,p_authorized,auth.uid()::text)returning gate_pass_id into v_id;for v_line in select value from jsonb_array_elements(p_lines)loop v_n:=v_n+1;insert into gate_pass_lines(gate_pass_id,line_no,description,quantity,uom_text,remarks,created_by)values(v_id,v_n,v_line->>'description',(v_line->>'quantity')::numeric,coalesce(nullif(v_line->>'uom',''),'PCS'),v_line->>'remarks',auth.uid()::text);end loop;insert into audit_log(user_id,action,entity_type,entity_id,new_value)values(auth.uid(),'Dispatch','gate_passes',v_id,jsonb_build_object('serial_no',v_no,'pass_type',p_type,'lines',v_n));return v_id;end $$;
alter table public.gate_passes enable row level security;alter table public.gate_pass_lines enable row level security;create policy factory_read_gate_passes on public.gate_passes for select using(has_factory_role(auth.uid(),array['admin','store','accounts','viewer']));create policy factory_read_gate_pass_lines on public.gate_pass_lines for select using(has_factory_role(auth.uid(),array['admin','store','accounts','viewer']));grant execute on function public.issue_gate_pass(text,text,text,text,text,text,text,text,text,text,jsonb)to authenticated;
